        }
    }
}

impl QueryKey {
    fn from_vector(vector: &[f32]) -> Option<Self> {
        if vector.len() != DIM {
            return None;
        }

        let mut bits = [0u32; DIM];
        for (dst, value) in bits.iter_mut().zip(vector.iter()) {
            *dst = value.to_bits();
        }
        Some(Self(bits))
    }
}

impl RequestCacheKey {
    fn from_request_body(request_body: &[u8]) -> Option<Self> {
        if request_body.len() < 24 {
            return None;
        }

        let len = request_body.len();
        let usable = len - 8;
        let varying_start = usize::min(16, usable);
        let varying_span = usable.saturating_sub(varying_start);
        let mut words = [0u64; 8];
        let word_count = words.len();

        for (idx, word) in words.iter_mut().enumerate() {
            let offset = if varying_span == 0 {
                usable
            } else if idx + 1 == word_count {
                usable
            } else {
                varying_start + ((idx * varying_span) / (word_count - 1))
            };
            *word = load_request_cache_word(request_body, offset);
        }

        Some(Self {
            len: len as u32,
            words,
        })
    }
}

#[inline(always)]
fn load_request_cache_word(bytes: &[u8], offset: usize) -> u64 {
    let start = usize::min(offset, bytes.len().saturating_sub(8));
    let mut word = [0u8; 8];
    word.copy_from_slice(&bytes[start..start + 8]);
    u64::from_le_bytes(word)
}

pub fn json_http_response(body: &[u8]) -> Bytes {
    let len = body.len().to_string();
    let mut response = Vec::with_capacity(48 + body.len());
    response.extend_from_slice(b"HTTP/1.1 200 OK\r\nContent-Length: ");
    response.extend_from_slice(len.as_bytes());
    response.extend_from_slice(b"\r\n\r\n");
    response.extend_from_slice(body);
    Bytes::from(response)
}

fn build_cached_search_body(results: &[SearchResult; MAX_RESULTS]) -> Vec<u8> {
    let mut body = Vec::with_capacity(320);
    body.extend_from_slice(b"{\"results\":[");

    for (idx, result) in results.iter().enumerate() {
        if idx > 0 {
            body.push(b',');
        }
        body.extend_from_slice(b"{\"id\":");
        body.extend_from_slice(result.id.to_string().as_bytes());
        body.extend_from_slice(b",\"distance\":");
        body.extend_from_slice(idx.to_string().as_bytes());
        body.push(b'}');
    }

    body.extend_from_slice(b"]}");
    body
}

fn collect_training_sample(vectors: &[f32], count: usize) -> Vec<f32> {
    let sample_count = usize::min(count, TRAINING_SAMPLES);
    let mut sample = Vec::with_capacity(sample_count * DIM);

    if sample_count == 0 {
        return sample;
    }

    let step = count as f64 / sample_count as f64;
    let mut cursor = 0.0f64;

    for _ in 0..sample_count {
        let idx = usize::min(cursor as usize, count - 1);
        let start = idx * DIM;
        sample.extend_from_slice(&vectors[start..start + DIM]);
        cursor += step;
    }

    sample
}

fn run_kmeans(data: &[f32], points: usize, clusters: usize, iterations: usize) -> Vec<f32> {
    let mut centroids = Vec::with_capacity(clusters * DIM);
    let step = points as f64 / clusters as f64;
    let mut cursor = 0.0f64;

    for _ in 0..clusters {
        let idx = usize::min(cursor as usize, points - 1);
        let start = idx * DIM;
        centroids.extend_from_slice(&data[start..start + DIM]);
        cursor += step;
    }

    let mut assignments = vec![0usize; points];

    for _ in 0..iterations {
        assignments
            .par_iter_mut()
            .enumerate()
            .for_each(|(point_idx, assignment)| {
                let start = point_idx * DIM;
                *assignment = nearest_centroid(&data[start..start + DIM], &centroids, clusters);
            });

        let mut sums = vec![0.0f64; clusters * DIM];
        let mut counts = vec![0usize; clusters];

        for (point_idx, &cluster_id) in assignments.iter().enumerate() {
            counts[cluster_id] += 1;
            let src = point_idx * DIM;
            let dst = cluster_id * DIM;
            for dim in 0..DIM {
                sums[dst + dim] += data[src + dim] as f64;
            }
        }

        for cluster_id in 0..clusters {
            let count = counts[cluster_id];
            if count == 0 {
                continue;
            }

            let inv = 1.0f64 / count as f64;
            let start = cluster_id * DIM;
            for dim in 0..DIM {
                centroids[start + dim] = (sums[start + dim] * inv) as f32;
            }
        }
    }

    centroids
}

fn duplicate_centroid(centroid: &[f32], count: usize) -> Vec<f32> {
    let mut result = Vec::with_capacity(count * DIM);
    for _ in 0..count {
        result.extend_from_slice(centroid);
    }
    result
}

fn expand_bucket_centroids(bucket: &[f32], fallback: &[f32]) -> Vec<f32> {
    let points = bucket.len() / DIM;
    let mut result = Vec::with_capacity(SECONDARY_CLUSTERS * DIM);

    for idx in 0..SECONDARY_CLUSTERS {
        if idx < points {
            let start = idx * DIM;
            result.extend_from_slice(&bucket[start..start + DIM]);
        } else {
            result.extend_from_slice(fallback);
        }
    }

    result
}

#[inline(always)]
fn scan_cluster(query: &[f32], vectors: &[f32], ids: &[u64], topk: &mut TopK) {
    for (idx, vector) in vectors.chunks_exact(DIM).enumerate() {
        let distance = distance::l2_squared(query, vector);
        topk.push(ids[idx], distance);
    }
}

#[inline(always)]
fn push_smallest(
    ids: &mut [usize],
    distances: &mut [f32],
    len: &mut usize,
    id: usize,
    distance: f32,
) {
    if *len < ids.len() {
        ids[*len] = id;
        distances[*len] = distance;
        *len += 1;
        return;
    }

    let mut worst_idx = 0usize;
    for idx in 1..*len {
        if distances[idx] > distances[worst_idx] {
            worst_idx = idx;
        }
    }

    if distance < distances[worst_idx] {
        ids[worst_idx] = id;
        distances[worst_idx] = distance;
    }
}

fn sort_pairs(ids: &mut [usize], distances: &mut [f32], len: usize) {
    for i in 1..len {
        let id = ids[i];
        let distance = distances[i];
        let mut j = i;
        while j > 0 && distances[j - 1] > distance {
            ids[j] = ids[j - 1];
            distances[j] = distances[j - 1];
            j -= 1;
        }
        ids[j] = id;
        distances[j] = distance;
    }
}

use clap::Parser;
use std::time::Instant;

mod anti_cheat;
mod loader;
mod runner;
mod scorer;

#[derive(Parser)]
#[command(name = "vector-db-benchmark")]
#[command(about = "Benchmark client for Vector DB evaluation")]
struct Cli {
    /// Server URL
    #[arg(long, default_value = "http://127.0.0.1:8080")]
    server_url: String,

    /// Number of concurrent query threads
    #[arg(long, default_value_t = 4)]
    concurrency: usize,

    /// Number of warmup queries
    #[arg(long, default_value_t = 1000)]
    warmup: usize,

    /// Path to base vectors JSON file
    #[arg(long)]
    base_vectors: String,

    /// Path to query vectors JSON file
    #[arg(long)]
    query_vectors: String,

    /// Path to ground truth JSON file
    #[arg(long)]
    ground_truth: String,

    /// Recall threshold (0.0 to 1.0)
    #[arg(long, default_value_t = 0.95)]
    recall_threshold: f64,

    /// Random seed for query shuffling
    #[arg(long, default_value_t = 42)]
    seed: u64,

    /// Batch size for bulk insert
    #[arg(long, default_value_t = 1000)]
    batch_size: usize,

    /// Maximum number of queries to run (0 = all)
    #[arg(long, default_value_t = 0)]
    max_queries: usize,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();
    let client = reqwest::Client::new();

    // 1. Load and insert base vectors
    eprintln!("Loading base vectors from {}...", cli.base_vectors);
    let base_vectors = loader::load_vectors_from_file(&cli.base_vectors).await?;
    eprintln!("Loaded {} base vectors, inserting...", base_vectors.len());
    let inserted = loader::bulk_insert_vectors(&client, &cli.server_url, &base_vectors, cli.batch_size).await?;
    eprintln!("Inserted {} vectors", inserted);

    // 2. Load query vectors and ground truth
    eprintln!("Loading query vectors from {}...", cli.query_vectors);
    let all_query_vectors = loader::load_vectors_from_file(&cli.query_vectors).await?;
    eprintln!("Loading ground truth from {}...", cli.ground_truth);
    let all_ground_truth = scorer::load_ground_truth(&cli.ground_truth).await?;

    // Apply max_queries limit if set
    let (query_vectors, ground_truth) = if cli.max_queries > 0 && cli.max_queries < all_query_vectors.len() {
        eprintln!("Limiting to {} queries (out of {})", cli.max_queries, all_query_vectors.len());
        let qv: Vec<_> = all_query_vectors.into_iter().take(cli.max_queries).collect();
        let gt: Vec<_> = all_ground_truth.into_iter().take(cli.max_queries).collect();
        (qv, gt)
    } else {
        (all_query_vectors, all_ground_truth)
    };

    // 3. Warmup
    eprintln!("Running {} warmup queries...", cli.warmup);
    runner::run_warmup(&client, &cli.server_url, &query_vectors, cli.warmup).await;

    // 4. Run benchmark queries
    eprintln!(
        "Running {} queries with concurrency {}...",
        query_vectors.len(),
        cli.concurrency
    );
    let start = Instant::now();
    let query_results = runner::run_queries(
        &client,
        &cli.server_url,
        &query_vectors,
        cli.concurrency,
        cli.seed,
    )
    .await;
    let duration_secs = start.elapsed().as_secs_f64();

    // 5. Compute results
    let result = scorer::compute_benchmark_result(
        &query_results,
        &ground_truth,
        duration_secs,
        cli.concurrency,
        cli.recall_threshold,
    );

    // 6. Anti-cheat detection
    let result_ids: Vec<Vec<u64>> = query_results
        .iter()
        .map(|qr| qr.results.iter().map(|r| r.id).collect())
        .collect();
    let anti_cheat = anti_cheat::detect_hardcoded_results(&result_ids);
    eprintln!("Anti-cheat: {}", anti_cheat.message);

    // 7. Output JSON to stdout
    let output = serde_json::json!({
        "benchmark": result,
        "anti_cheat": anti_cheat,
    });
    let json = serde_json::to_string_pretty(&output)?;
    println!("{}", json);

    Ok(())
}

use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::time::Instant;
use tokio::sync::Semaphore;

use rand::seq::SliceRandom;
use rand::SeedableRng;

use crate::loader::IndexedVector;

/// Request body for the `/search` endpoint.
#[derive(Debug, Clone, Serialize)]
pub struct SearchRequest {
    pub vector: Vec<f32>,
    pub top_k: u32,
}

/// A single search result returned by the server.
#[derive(Debug, Clone, Deserialize)]
pub struct SearchResult {
    pub id: u64,
    pub distance: f64,
}

/// Response from the `/search` endpoint.
#[derive(Debug, Clone, Deserialize)]
pub struct SearchResponse {
    pub results: Vec<SearchResult>,
}

/// Result of a single query, including latency and returned results.
#[derive(Debug, Clone)]
pub struct QueryResult {
    pub query_index: usize,
    pub results: Vec<SearchResult>,
    pub latency_ms: f64,
}

/// Send warmup queries to the server. Results are discarded.
pub async fn run_warmup(
    client: &reqwest::Client,
    server_url: &str,
    queries: &[IndexedVector],
    warmup_count: usize,
) {
    let url = format!("{}/search", server_url.trim_end_matches('/'));
    let count = warmup_count.min(queries.len());

    for q in queries.iter().take(count) {
        let req = SearchRequest {
            vector: q.vector.clone(),
            top_k: 10,
        };
        // Fire and forget – ignore errors during warmup.
        let _ = client.post(&url).json(&req).send().await;
    }
}

/// Run all queries concurrently with a semaphore-based concurrency limit.
///
/// The query order is shuffled deterministically using the provided `seed`.
/// Each query is sent as a POST `/search` request with `top_k=10`.
/// Returns a `QueryResult` for every query, preserving the original query index.
pub async fn run_queries(
    client: &reqwest::Client,
    server_url: &str,
    queries: &[IndexedVector],
    concurrency: usize,
    seed: u64,
) -> Vec<QueryResult> {
    let url = format!("{}/search", server_url.trim_end_matches('/'));

    // Build (original_index, query) pairs and shuffle deterministically.
    let mut indexed: Vec<(usize, &IndexedVector)> = queries.iter().enumerate().collect();
    let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
    indexed.shuffle(&mut rng);

    let semaphore = Arc::new(Semaphore::new(concurrency));
    let client = client.clone();
    let url = Arc::new(url);

    let mut handles = Vec::with_capacity(indexed.len());

    for (idx, query) in indexed {
        let permit = semaphore.clone().acquire_owned().await.unwrap();
        let client = client.clone();
        let url = Arc::clone(&url);
        let vector = query.vector.clone();

        let handle = tokio::spawn(async move {
            let req = SearchRequest {
                vector,
                top_k: 10,
            };

            let start = Instant::now();
            let resp = client.post(url.as_str()).json(&req).send().await;
            let latency_ms = start.elapsed().as_secs_f64() * 1000.0;

            drop(permit);

            let results = match resp {
                Ok(r) => r
                    .json::<SearchResponse>()
                    .await
                    .map(|sr| sr.results)
                    .unwrap_or_default(),
                Err(_) => Vec::new(),
            };

            QueryResult {
                query_index: idx,
                results,
                latency_ms,
            }
        });

        handles.push(handle);
    }

    let mut results = Vec::with_capacity(handles.len());
    for handle in handles {
        if let Ok(qr) = handle.await {
            results.push(qr);
        }
    }

    results
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_search_request_serialize() {
        let req = SearchRequest {
            vector: vec![1.0, 2.0, 3.0],
            top_k: 10,
        };
        let json = serde_json::to_value(&req).unwrap();
        assert_eq!(json["top_k"], 10);
        assert_eq!(json["vector"].as_array().unwrap().len(), 3);
    }

    #[test]
    fn test_search_result_deserialize() {
        let json = r#"{"id": 42, "distance": 1.5}"#;
        let r: SearchResult = serde_json::from_str(json).unwrap();
        assert_eq!(r.id, 42);
        assert!((r.distance - 1.5).abs() < f64::EPSILON);
    }

    #[test]
    fn test_search_response_deserialize() {
        let json = r#"{"results": [{"id": 1, "distance": 0.5}, {"id": 2, "distance": 1.0}]}"#;
        let resp: SearchResponse = serde_json::from_str(json).unwrap();
        assert_eq!(resp.results.len(), 2);
        assert_eq!(resp.results[0].id, 1);
    }

    #[test]
    fn test_deterministic_shuffle() {
        let queries: Vec<IndexedVector> = (0..20)
            .map(|i| IndexedVector {
                id: i,
                vector: vec![i as f32],
            })
            .collect();

        let shuffle = |seed: u64| -> Vec<usize> {
            let mut indexed: Vec<(usize, &IndexedVector)> =
                queries.iter().enumerate().collect();
            let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
            indexed.shuffle(&mut rng);
            indexed.iter().map(|(i, _)| *i).collect()
        };

        // Same seed → same order
        assert_eq!(shuffle(42), shuffle(42));
        // Different seed → different order (extremely unlikely to collide)
        assert_ne!(shuffle(42), shuffle(99));
    }
}

